<?php session_start();require_once __DIR__.'/../../conn.php';require_once __DIR__.'/../../auth.php';requireStaff();require_once __DIR__.'/../../sort_utils.php';$allowed=['customer_id'=>'ID','customer_name'=>'Name','password'=>'Password','contact_number'=>'Contact','address'=>'Address'];list($sort,$order)=get_sort_params($allowed,'customer_id');$msg='';$mt='';if($_SERVER['REQUEST_METHOD']==='POST'){$cid=(int)$_POST['customer_id'];if(isset($_POST['delete'])){$chk=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) as cnt FROM Orders WHERE customer_id=$cid"))['cnt'];if($chk>0){$msg="Cannot delete: {$chk} order(s) exist.";$mt='error';}else{mysqli_query($conn,"DELETE FROM Customer WHERE customer_id=$cid");$msg='Customer deleted.';$mt='success';}}elseif(isset($_POST['update'])){$n=trim($_POST['customer_name']);$p=trim($_POST['password']);$ph=trim(isset($_POST['contact_number'])?$_POST['contact_number']:'');$a=trim(isset($_POST['address'])?$_POST['address']:'');$s=mysqli_prepare($conn,"UPDATE Customer SET customer_name=?,password=?,contact_number=?,address=? WHERE customer_id=?");mysqli_stmt_bind_param($s,'ssssi',$n,$p,$ph,$a,$cid);if(mysqli_stmt_execute($s)){$msg='Customer updated.';$mt='success';}else{$msg='Update failed.';$mt='error';}mysqli_stmt_close($s);}}$r=mysqli_query($conn,"SELECT * FROM Customer ".sort_clause($sort,$order));$rs=array();while($rw=mysqli_fetch_assoc($r))$rs[]=$rw;mysqli_free_result($r);$oc=array();$or=mysqli_query($conn,"SELECT customer_id,COUNT(*) as cnt FROM Orders GROUP BY customer_id");while($ow=mysqli_fetch_assoc($or))$oc[$ow['customer_id']]=$ow['cnt'];mysqli_close($conn);?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Manage Customers</title><link rel="stylesheet" href="../style.css"><style>.mc{flex:1;display:flex;flex-direction:column;overflow-y:auto;padding:24px 32px}.tw{background:#fff;border-radius:20px;padding:20px;overflow-x:auto;box-shadow:0 1px 3px rgba(0,0,0,.06)}.m{padding:12px 16px;border-radius:10px;margin-bottom:16px;font-weight:500;font-size:.9rem}.me{background:#fef2f2;color:#991b1b;border:1px solid #fecaca}.ms{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:10px 12px;border-bottom:1px solid #e0e0e0;text-align:center}th{font-weight:500;color:#5f6368;font-size:13px}.is{padding:6px 8px;border-radius:6px;border:1px solid #dadce0;font-size:12px;width:90px}.bs{padding:6px 12px;border-radius:16px;font-size:12px;font-weight:500;cursor:pointer;border:none;color:#fff;background:#1a73e8}.bs:hover{background:#1557b0}.bd{background:#d93025}.bd:hover{background:#b3261e}.bs:disabled{background:#9aa0a6;cursor:not-allowed}</style></head><body><div id="sidebar-container"></div><div class="mc"><div class="top-bar"><div class="page-title">Manage Customers</div></div><div class="content-container"><?php if($msg):?><div class="m m<?php echo $mt[0];?>"><?php echo htmlspecialchars($msg);?></div><?php endif;?><div class="tw"><table><thead><tr><?php echo sortable_th('customer_id','ID',$sort,$order);?><th><?php echo sortable_th('customer_name','Name',$sort,$order);?></th><th><?php echo sortable_th('password','Password',$sort,$order);?></th><th><?php echo sortable_th('contact_number','Contact',$sort,$order);?></th><th><?php echo sortable_th('address','Address',$sort,$order);?><th>Orders</th><th>Edit</th><th>Delete</th></tr></thead><tbody><?php foreach($rs as $rw):$cid=$rw['customer_id'];$cnt=isset($oc[$cid])?$oc[$cid]:0;?><tr><form method="post"><input type="hidden" name="customer_id" value="<?php echo $cid;?>"><td><?php echo $cid;?></td><td><input type="text" name="customer_name" value="<?php echo htmlspecialchars($rw['customer_name']);?>" class="is" required></td><td><input type="text" name="password" value="<?php echo htmlspecialchars($rw['password']);?>" class="is"></td><td><input type="text" name="contact_number" value="<?php echo htmlspecialchars(isset($rw['contact_number'])?$rw['contact_number']:'');?>" class="is"></td><td><input type="text" name="address" value="<?php echo htmlspecialchars(isset($rw['address'])?$rw['address']:'');?>" class="is"></td><td><?php echo $cnt;?></td><td><button type="submit" name="update" value="1" class="bs">Save</button></td><td><button type="submit" name="delete" value="1" class="bs bd" <?php echo $cnt>0?'disabled':'';?> onclick="<?php echo $cnt>0?'':'return confirm(\'Delete this customer?\');';?>">Del</button> <small style="color:<?php echo $cnt>0?'#d93025':'#5f6368';?>">(<?php echo $cnt;?> order(s))</small></td></form></tr><?php endforeach;?></tbody></table></div></div></div><script src="../sidebar.js"></script><script>loadSidebar('manage-customers');</script></body></html>
